components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background: oklch(0.491 0.27 292.581);
  color: oklch(0.969 0.016 293.756);
  font-family: Geist, system-ui, -apple-system, sans-serif;
  font-size: 0.9375rem;
  font-weight: 500;
  line-height: 1;
  padding: 0.625rem 1.25rem;
  border: none;
  border-radius: 0.625rem;
  cursor: pointer;
  transition: background 0.15s cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-btn-primary:hover {
  background: oklch(0.43 0.27 292.581);
}
.ds-btn-primary:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px oklch(0.985 0.004 290), 0 0 0 4px oklch(0.72 0.01 290);
}
.ds-btn-primary:active {
  background: oklch(0.38 0.27 292.581);
  transform: scale(0.98);
}

.ds-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background: oklch(0.965 0.004 290);
  color: oklch(0.28 0.004 290);
  font-family: Geist, system-ui, -apple-system, sans-serif;
  font-size: 0.9375rem;
  font-weight: 500;
  line-height: 1;
  padding: 0.625rem 1.25rem;
  border: none;
  border-radius: 0.625rem;
  cursor: pointer;
  transition: background 0.15s cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-btn-secondary:hover {
  background: oklch(0.91 0.005 290);
}
.ds-btn-secondary:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px oklch(0.985 0.004 290), 0 0 0 4px oklch(0.72 0.01 290);
}

.ds-field {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.ds-label {
  font-family: Geist, system-ui, -apple-system, sans-serif;
  font-size: 0.9375rem;
  font-weight: 500;
  color: oklch(0.18 0.004 290);
  line-height: 1.4;
}
.ds-input {
  font-family: Geist, system-ui, -apple-system, sans-serif;
  font-size: 0.9375rem;
  color: oklch(0.18 0.004 290);
  background: oklch(0.985 0.004 290);
  border: 1px solid oklch(0.91 0.005 290);
  border-radius: 0.625rem;
  padding: 0.625rem 0.875rem;
  line-height: 1.5;
  transition: border-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.15s cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-input::placeholder {
  color: oklch(0.57 0.01 290);
}
.ds-input:focus {
  outline: none;
  border-color: oklch(0.491 0.27 292.581);
  box-shadow: 0 0 0 2px oklch(0.985 0.004 290), 0 0 0 4px oklch(0.72 0.01 290);
}
.ds-input:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.ds-card {
  background: oklch(0.985 0.004 290);
  border: 1px solid oklch(0.91 0.005 290);
  border-radius: 0.625rem;
  padding: 1.5rem;
}
.ds-card-title {
  font-family: Geist, system-ui, -apple-system, sans-serif;
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.01em;
  color: oklch(0.57 0.01 290);
  margin: 0 0 0.5rem 0;
  text-transform: uppercase;
}
.ds-card-value {
  font-family: Geist Mono, ui-monospace, monospace;
  font-size: 1.5rem;
  font-weight: 600;
  color: oklch(0.18 0.004 290);
  margin: 0 0 0.25rem 0;
  line-height: 1.2;
}
.ds-card-desc {
  font-family: Geist, system-ui, -apple-system, sans-serif;
  font-size: 0.9375rem;
  color: oklch(0.57 0.01 290);
  margin: 0;
  line-height: 1.5;
}
.ds-card:hover {
  box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.ds-chip-success {
  display: inline-flex;
  align-items: center;
  font-family: Geist, system-ui, -apple-system, sans-serif;
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.01em;
  padding: 0.125rem 0.625rem;
  border-radius: 0.375rem;
  background: oklch(0.491 0.27 292.581 / 0.1);
  color: oklch(0.491 0.27 292.581);
  line-height: 1.6;
}

.ds-chip-error {
  display: inline-flex;
  align-items: center;
  font-family: Geist, system-ui, -apple-system, sans-serif;
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.01em;
  padding: 0.125rem 0.625rem;
  border-radius: 0.375rem;
  background: oklch(0.577 0.245 27.325 / 0.1);
  color: oklch(0.577 0.245 27.325);
  line-height: 1.6;
}

.ds-sidebar {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 1rem 0.75rem;
  background: oklch(0.985 0.004 290);
  border-right: 1px solid oklch(0.91 0.005 290);
  min-width: 240px;
  height: 100%;
}
.ds-nav-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem 0.75rem;
  border-radius: 0.5rem;
  font-family: Geist, system-ui, -apple-system, sans-serif;
  font-size: 0.9375rem;
  font-weight: 400;
  color: oklch(0.57 0.01 290);
  text-decoration: none;
  cursor: pointer;
  transition: background 0.15s cubic-bezier(0.4, 0, 0.2, 1), color 0.15s cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-nav-item:hover {
  background: oklch(0.965 0.004 290);
  color: oklch(0.28 0.004 290);
}
.ds-nav-item.active {
  background: oklch(0.491 0.27 292.581 / 0.08);
  color: oklch(0.491 0.27 292.581);
  font-weight: 500;
}
